async function send(web,o){try{await web.evaluateJavaScript(`window.__native(${JSON.stringify(o)})`,false)}catch(_){}}
async function settings(s){
  const web=new WebView();
  await web.loadHTML(html(s));
  let dismissed=false;
  const presentPromise=web.present(false).then(()=>{dismissed=true});
  let cur=merge(s);
  const sleep=ms=>new Promise(resolve=>Timer.schedule(ms,false,resolve));
  while(!dismissed){
    await sleep(160);
    if(dismissed)break;
    let raw=null;
    try{raw=await web.evaluateJavaScript("JSON.stringify(window.__nativeQueue.shift()||null)")}catch(_){if(dismissed)break;continue}
    if(!raw||raw==="null")continue;
    let m=null;try{m=JSON.parse(raw)}catch(_){continue}
    if(!m?.action)continue;
    try{
      if(m.action==="save"){
        cur=merge(m.settings);saveSettings(cur)
      }else if(m.action==="teams"){
        const tmp=merge(m.settings||cur),a=await teamsFor(tmp);cur=tmp;saveSettings(cur);await send(web,{action:"teams",ok:!!a.length,teams:a})
      }else if(m.action==="diagnostics"){
        const tmp=merge(m.settings||cur);cur=tmp;saveSettings(cur);const rows=await collectDiagnostics(tmp,async r=>await send(web,{action:"diagnostics",rows:r}));await send(web,{action:"diagnostics",rows})
      }else if(m.action==="preview"){
        cur=merge(m.settings||cur);saveSettings(cur);const fam=["small","medium","large"].includes(m.family)?m.family:"medium";LAST_AUTO_TABLE_LAYOUT=null;try{const w=await widget(cur,fam);if(LAST_AUTO_TABLE_LAYOUT)await send(web,{action:"autoTableInfo",info:LAST_AUTO_TABLE_LAYOUT});if(fam==="small")await w.presentSmall();else if(fam==="large")await w.presentLarge();else await w.presentMedium()}finally{await send(web,{action:"previewDone",family:fam})}
      }else if(m.action==="export"){
        cur=merge(m.settings);saveSettings(cur);Pasteboard.copyString(JSON.stringify(cur,null,2));await send(web,{action:"status",ok:true,text:tx(cur,"copied")})
      }else if(m.action==="import"){
        try{cur=merge(JSON.parse(m.raw||""));if(!cur.language)cur.language=s.language||lang();saveSettings(cur);await send(web,{action:"status",ok:true,text:tx(cur,"imported")});await send(web,{action:"replace",settings:cur})}catch(_){await send(web,{action:"status",ok:false,text:tx(cur,"invalid")})}
      }else if(m.action==="clearCache"){
        try{const dir=fm.cacheDirectory();for(const name of fm.listContents(dir))if(name===CACHE_FILE||(name.startsWith("SportsInfo_")&&name.endsWith(".png"))||name.startsWith("logo_")){try{fm.remove(fm.joinPath(dir,name))}catch(_){}}}catch(_){}await send(web,{action:"status",ok:true,text:tx(cur,"cacheCleared")})
      }else if(m.action==="reset"){
        const base=merge(m.settings||cur),l=base.language||lang();if(m.part==="appearance")cur=Object.assign({},base,{theme:DEFAULTS.theme,accent:DEFAULTS.accent,background:DEFAULTS.background,panelColor:DEFAULTS.panelColor,textColor:DEFAULTS.textColor,mutedColor:DEFAULTS.mutedColor,liveColor:DEFAULTS.liveColor,winColor:DEFAULTS.winColor,compact:DEFAULTS.compact,refreshMinutes:DEFAULTS.refreshMinutes});else if(m.part==="sport")cur=Object.assign({},base,{sportId:DEFAULTS.sportId,leagueId:DEFAULTS.leagueId,teamId:"",teamName:""});else{cur=clone(DEFAULTS);cur.language=l}saveSettings(cur);await send(web,{action:"status",ok:true,text:tx(cur,"resetDone")});await send(web,{action:"replace",settings:cur})
      }else if(m.action==="update"){
        cur=merge(m.settings||cur);saveSettings(cur);const r=await updater(cur);await send(web,{action:"update",ok:r.ok,text:r.text})
      }
    }catch(e){await send(web,{action:"status",ok:false,text:String(e)})}
  }
  try{await presentPromise}catch(_){}
  return cur
}
function cmp(a,b){const A=String(a).split('.').map(Number),B=String(b).split('.').map(Number);for(let i=0;i<Math.max(A.length,B.length);i++){if((A[i]||0)>(B[i]||0))return 1;if((A[i]||0)<(B[i]||0))return-1}return 0}
async function updater(s){try{const src=await getString(UPDATE_SOURCE_URL);if(!src||src.length<UPDATE_MIN_BYTES)throw new Error("Bad source");const m=src.match(/const APP_VERSION\s*=\s*"([^"]+)"/);if(!m)throw new Error("No version");const v=m[1];if(cmp(v,APP_VERSION)<=0)return{ok:true,text:`${tx(s,"current")} v${APP_VERSION}`};const a=new Alert();a.title=APP_NAME;a.message=`${tx(s,"available")}: v${v}`;a.addAction(tx(s,"apply"));a.addCancelAction(tx(s,"cancel"));if(await a.presentAlert()!==0)return{ok:true,text:`v${APP_VERSION} → v${v}`};const target=module.filename;if(!target)throw new Error("Current script path unavailable");const cloud=FileManager.iCloud(),local=FileManager.local();let targetFm=local;if(cloud.fileExists(target)){targetFm=cloud;if(!cloud.isFileDownloaded(target))await cloud.downloadFileFromiCloud(target)}else if(!local.fileExists(target))throw new Error("Current script file not found");const b=/\.js$/i.test(target)?target.replace(/\.js$/i,`_backup_v${APP_VERSION}.js`):target+`_backup_v${APP_VERSION}.js`;try{targetFm.writeString(b,targetFm.readString(target))}catch(_){}targetFm.writeString(target,src);return{ok:true,text:tx(s,"updatedOk")}}catch(e){console.log(e);return{ok:false,text:tx(s,"updateFail")}}}

let SETTINGS=await firstLanguage(loadSettings());
const PREVIEW_FAMILY=String(args.queryParameters?.sportsPreview||"");
if(config.runsInWidget){
  const w=await widget(SETTINGS,config.widgetFamily||"medium");Script.setWidget(w)
}else if(["small","medium","large"].includes(PREVIEW_FAMILY)){
  const w=await widget(SETTINGS,PREVIEW_FAMILY);
  if(PREVIEW_FAMILY==="small")await w.presentSmall();else if(PREVIEW_FAMILY==="large")await w.presentLarge();else await w.presentMedium();
  await settings(SETTINGS)
}else await settings(SETTINGS);
Script.complete();
